  if (y->sz > x->sz) {
    mpz_clear(mrb, y);
    mpz_init(mrb, y);
    mpz_realloc(mrb, y, (size_t)(x->sz));
  }

  for (i=0;i < k; i++)
    (y->p)[i] = (x->p)[i];

  for (;i<y->sz;i++)
    (y->p)[i] = 0;

  y->sn = x->sn;
}

